@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
    </div>
}
else
{
    <div class="d-flex">
        <!-- Left Sidebar -->
        <div class="pe-4" style="width: 25%; min-width: 220px;">
            <h5>Filters</h5>

            @if (_categories is not null)
            {
                <div class="mb-3">
                    <label class="form-label fw-bold">Categories</label>
                    @foreach (var category in _categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                   checked="@(_selectedCategories.Contains(category))"
                                   @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                        </div>
                    }
                </div>
            }

            <div class="mb-3">
                <label class="form-label fw-bold">Price Range</label>
                <div class="d-flex gap-2 align-items-center">
                    <input type="number" class="form-control" placeholder="Min" @bind="_minPrice" />
                    <span>–</span>
                    <input type="number" class="form-control" placeholder="Max" @bind="_maxPrice" />
                </div>
            </div>

            <div class="mb-3 form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="_inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
                <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
            </div>
        </div>

        <!-- Main Content -->
        <div style="width: 75%;">
            <!-- Toolbar -->
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="me-2">Sort by:</label>
                    <select class="form-select d-inline-block w-auto" @onchange="OnSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                @if (_result is not null && _result.TotalCount > 0)
                {
                    var first = (_result.Page - 1) * _result.PageSize + 1;
                    var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                    <span class="text-muted">Showing @first–@last of @_result.TotalCount products</span>
                }
            </div>

            <!-- Content States -->
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2">Loading products...</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div class="text-center py-5">
                    <p class="text-muted fs-5">No products found matching your criteria.</p>
                </div>
            }
            else
            {
                <!-- Product Grid -->
                <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
                    @foreach (var product in _result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product" OnProductSelected="OnProductSelected" />
                        </div>
                    }
                </div>

                <!-- Pagination -->
                @if (TotalPages > 1)
                {
                    <nav class="mt-4" aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(_currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(_currentPage - 1)" disabled="@(_currentPage == 1)">Previous</button>
                            </li>
                            @for (int i = 1; i <= TotalPages; i++)
                            {
                                var pageNum = i;
                                <li class="page-item @(pageNum == _currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(_currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(_currentPage + 1)" disabled="@(_currentPage == TotalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;

    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        StateHasChanged();

        try
        {
            var filter = new ProductFilter(
                Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
                MinPrice: _minPrice,
                MaxPrice: _maxPrice,
                InStockOnly: _inStockOnly
            );

            _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
            _error = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        _currentPage = page;
        await LoadProducts();
    }

    private void OnProductSelected(Product product)
    {
        // Parent page handles navigation to detail page
    }
}

@namespace sv_744f32fc511b4e0faedb74308065e979.Components.Pages

<div class="card h-100 product-card" @onclick="HandleCardClick" style="cursor: pointer;">
    <div class="card-img-top bg-light d-flex align-items-center justify-content-center" style="height: 180px;" role="img" aria-label="@Product.Name">
        <span class="text-muted">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title">@Product.Name</h6>
        <p class="card-text fw-bold text-primary">@Product.Price.ToString("C")</p>
        <p class="card-text">@GetStarRating(Product.Rating)</p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        // Add to cart logic would go here
        await Task.CompletedTask;
    }

    private static string GetStarRating(double rating)
    {
        var fullStars = (int)Math.Round(rating);
        var emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

